function inScope(siteId){if(S.site!=='all')return siteId===S.site;if(S.country!=='all')return siteById(siteId).country===S.country;return true}
function siteHealth(id){const inc=INCIDENTS.filter(i=>i.site===id&&i.state!=='Closed');if(inc.some(i=>i.pri==='P1'))return'bad';const lk=LINKS.filter(l=>l.site===id).map(linkState);if(lk.length&&lk.every(x=>x==='bad'))return'bad';if(inc.some(i=>i.pri==='P2')||lk.includes('bad')||lk.includes('warn'))return'warn';return'good'}
function counts(){const r={good:0,warn:0,bad:0};SITES.filter(s=>inScope(s.id)).forEach(s=>r[siteHealth(s.id)]++);return r}
const openIncs=()=>INCIDENTS.filter(i=>i.state!=='Closed'&&inScope(i.site));
function slaState(i){const u=(S.now-i.opened)/mins(PRIORITY[i.pri].tts);return{used:u,left:PRIORITY[i.pri].tts-(S.now-i.opened)/60000,st:u>=1?'bad':u>=.75?'warn':'good'}}

/* live registry: L(fn) renders now and refreshes on every tick */
let LIVE=[];
function L(fn0,tag="span"){const fn=()=>tok(fn0());const id=LIVE.length;LIVE.push(fn);let v="";try{v=fn()}catch(e){console.error(e)}return `<${tag} data-l="${id}">${v}</${tag}>`}
function refreshLive(){$$('[data-l]').forEach(el=>{const f=LIVE[+el.dataset.l];if(!f)return;let v;try{v=f()}catch(e){return}if(el._v!==v){el._v=v;el.innerHTML=v}})}

function tick(){const dt=2000*S.speed;S.now+=dt;
 for(const k in M){const a=M[k];const b=a[0];let v=a[a.length-1];const amp={events:10,avail:.012,mtta:.25,mttr:1.2,noise:.12,eps:150,gb:3,fw:6,sap:26,open:0}[k]||1;v+=(rnd()-.5)*amp;const mean=a.reduce((x,y)=>x+y,0)/a.length;v+=(mean-v)*.1;a.push(+v.toFixed(2));a.shift()}
 M.open[M.open.length-1]=INCIDENTS.filter(i=>i.state!=='Closed').length;
 LINKS.forEach(l=>{if(l.given==null)l.util=Math.max(3,Math.min(97,l.util+(rnd()-.5)*2+(BASE_UTIL[l.id]-l.util)*.1));l.lat=Math.max(6,l.lat+(rnd()-.5)*2);if(l.id!=='L12')l.loss=Math.max(0,Math.min(1.2,l.loss+(rnd()-.5)*.08))});
 Object.values(VMSTATE).forEach(v=>{v.cpu=Math.max(4,Math.min(96,v.cpu+(rnd()-.5)*4));v.mem=Math.max(10,Math.min(95,v.mem+(rnd()-.5)*1.5))});
 if(rnd()<.55)pushEvent();
 if(rnd()<.018*S.speed)toast('Heads-up',pick(['A carrier maintenance window opens at Jeddah tonight.','Patch ring 2 pre-checks passed on 12 servers.','Copilot closed 3 password resets in the last hour.','Backup success for last night finished at 99.1%.']));
 const c=$('#clock');if(c)c.textContent=hhmmss(S.now)+' IST';refreshLive()}
function toast(t,b){const w=$('#toasts');if(!w)return;const d=document.createElement('div');d.className='toast';d.innerHTML=`<b>${esc(t)}</b>${esc(b)}<button aria-label="Close">×</button>`;d.querySelector('button').onclick=()=>d.remove();w.prepend(d);while(w.children.length>3)w.lastChild.remove();setTimeout(()=>d.remove(),7000);S.notif.unshift({t:S.now,title:t,body:b})}

/* ---------- charts (SVG, one axis, thin marks, hover via data-tip) ---------- */
function spark(a,color='var(--s1)',w=120,h=28){const mn=Math.min(...a),mx=Math.max(...a),r=mx-mn||1;const p=a.map((v,i)=>[(i/(a.length-1))*(w-4)+2,h-4-(v-mn)/r*(h-8)]);const d=p.map((q,i)=>(i?'L':'M')+q[0].toFixed(1)+' '+q[1].toFixed(1)).join('');const e=p[p.length-1];return `<svg viewBox="0 0 ${w} ${h}" width="100%" height="${h}" preserveAspectRatio="none" aria-hidden="true"><path d="${d}" fill="none" stroke="${color}" stroke-width="1.6" vector-effect="non-scaling-stroke"/><circle cx="${e[0]}" cy="${e[1]}" r="2.2" fill="${color}"/></svg>`}
function nice(mx){if(mx<=0)return 1;const p=Math.pow(10,Math.floor(Math.log10(mx)));const n=mx/p;return (n<=1?1:n<=2?2:n<=5?5:10)*p}
function lineChart(series,o={}){const w=o.w||640,h=o.h||190,l=44,r=12,t=10,b=22;const all=series.flatMap(s=>s.data);if(o.threshold!=null)all.push(o.threshold);let mx=o.max!=null?o.max:nice(Math.max(...all)*1.05),mn=o.min!=null?o.min:0;const n=series[0].data.length;const X=i=>l+i/(n-1)*(w-l-r),Y=v=>t+(1-(v-mn)/(mx-mn))*(h-t-b);let s=`<svg viewBox="0 0 ${w} ${h}" width="100%" role="img" aria-label="${esc(o.label||'Line chart')}">`;for(let i=0;i<=4;i++){const v=mn+(mx-mn)*i/4,y=Y(v);s+=`<line x1="${l}" x2="${w-r}" y1="${y}" y2="${y}" stroke="var(--grid)"/><text x="${l-6}" y="${y+3.5}" text-anchor="end" font-size="10.5" fill="var(--ink3)">${+v.toFixed(mx-mn<10?1:0)}</text>`}
 (o.xl||[]).forEach(x=>{s+=`<text x="${X(x[0])}" y="${h-6}" text-anchor="middle" font-size="10.5" fill="var(--ink3)">${x[1]}</text>`});
 if(o.threshold!=null){s+=`<line x1="${l}" x2="${w-r}" y1="${Y(o.threshold)}" y2="${Y(o.threshold)}" stroke="var(--bad)" stroke-dasharray="4 3"/><text x="${w-r}" y="${Y(o.threshold)-4}" text-anchor="end" font-size="10.5" fill="var(--bad)">${esc(o.tlabel||'threshold')}</text>`}
 series.forEach(z=>{const c=z.color||'var(--s1)';s+=`<path d="${z.data.map((v,i)=>(i?'L':'M')+X(i).toFixed(1)+' '+Y(v).toFixed(1)).join('')}" fill="none" stroke="${c}" stroke-width="2" stroke-linejoin="round"/>`;const li=z.data.length-1;s+=`<circle cx="${X(li)}" cy="${Y(z.data[li])}" r="3.5" fill="${c}" stroke="var(--card)" stroke-width="1.5"/>`});
 const cw=(w-l-r)/(n-1);for(let i=0;i<n;i++){const tip=(o.xf?o.xf(i)+'\n':'')+series.map(z=>z.name+': '+z.data[i]+(o.unit||'')).join('\n');s+=`<rect x="${X(i)-cw/2}" y="${t}" width="${cw}" height="${h-t-b}" fill="transparent" data-tip="${esc(tip)}"/>`}
 return s+'</svg>'+(series.length>1?`<div class="legend" style="margin-top:4px">${series.map(z=>`<span><i style="background:${z.color||'var(--s1)'}"></i>${esc(z.name)}</span>`).join('')}</div>`:'')}
function barChart(items,o={}){const w=o.w||640,h=o.h||180,l=40,r=8,t=8,b=24;const mx=o.max||nice(Math.max(...items.map(i=>i.value))*1.05);const n=items.length,band=(w-l-r)/n,bw=Math.min(band-2,Math.max(band*.62,4));const Y=v=>t+(1-v/mx)*(h-t-b);let s=`<svg viewBox="0 0 ${w} ${h}" width="100%" role="img" aria-label="${esc(o.label||'Bar chart')}">`;for(let i=0;i<=4;i++){const v=mx*i/4,y=Y(v);s+=`<line x1="${l}" x2="${w-r}" y1="${y}" y2="${y}" stroke="var(--grid)"/><text x="${l-6}" y="${y+3.5}" text-anchor="end" font-size="10.5" fill="var(--ink3)">${+v.toFixed(mx<10?1:0)}</text>`}
 items.forEach((it,i)=>{const x=l+i*band+(band-bw)/2,y=Y(it.value),H=Math.max(0,h-b-y);s+=`<rect x="${x}" y="${y}" width="${bw}" height="${H}" rx="${Math.min(3,bw/2)}" fill="${it.color||'var(--s1)'}"/><rect x="${l+i*band}" y="${t}" width="${band}" height="${h-t-b}" fill="transparent" data-tip="${esc(it.tip||it.label+': '+it.value)}"/>`;if(!o.skip||i%o.skip===0)s+=`<text x="${x+bw/2}" y="${h-8}" text-anchor="middle" font-size="10.5" fill="var(--ink3)">${esc(it.label)}</text>`});return s+'</svg>'}
function donut(parts,center,sub){const R=62,C=2*Math.PI*R,tot=parts.reduce((a,p)=>a+p.value,0)||1;let off=0,s=`<svg viewBox="0 0 170 170" width="100%" style="max-width:190px" role="img" aria-label="Share chart">`;parts.forEach(p=>{const len=p.value/tot*C;s+=`<circle cx="85" cy="85" r="${R}" fill="none" stroke="${p.color}" stroke-width="20" stroke-dasharray="${Math.max(0,len-2)} ${C-Math.max(0,len-2)}" stroke-dashoffset="${-off}" transform="rotate(-90 85 85)" data-tip="${esc(p.label+': '+(p.text||p.value))}"/>`;off+=len});s+=`<text x="85" y="84" text-anchor="middle" font-size="21" font-weight="700" fill="var(--ink)">${esc(center)}</text><text x="85" y="102" text-anchor="middle" font-size="11" fill="var(--ink3)">${esc(sub||'')}</text></svg>`;return s}
function gauge(v,label,st){const c=st==='bad'?'var(--bad)':st==='warn'?'var(--warnbar)':'var(--good)',R=36,C=Math.PI*R,len=Math.min(100,Math.max(0,v))/100*C;return `<svg viewBox="0 0 100 60" width="100%" style="max-width:130px" role="img" aria-label="${esc(label)} ${Math.round(v)} percent"><path d="M14 52A36 36 0 0 1 86 52" fill="none" stroke="var(--grid)" stroke-width="8" stroke-linecap="round"/><path d="M14 52A36 36 0 0 1 86 52" fill="none" stroke="${c}" stroke-width="8" stroke-linecap="round" stroke-dasharray="${len} ${C}"/><text x="50" y="49" text-anchor="middle" font-size="16" font-weight="700" fill="var(--ink)">${Math.round(v)}%</text></svg><div class="note" style="text-align:center">${esc(label)}</div>`}
const hb=(label,v,max,cls,txt)=>`<div class="hb"><span title="${esc(label)}" style="overflow:hidden;text-overflow:ellipsis;white-space:nowrap">${esc(label)}</span><div class="bar"><i class="${cls||''}" style="width:${Math.min(100,v/max*100)}%"></i></div><span class="val">${txt!=null?txt:v}</span></div>`;
const tile=(l,v,s,cls)=>`<div class="card tile"><div class="l">${l}</div><div class="v ${cls||''}">${v}</div>${s?`<div class="s">${s}</div>`:''}</div>`;
const chip=(t,c)=>`<span class="chip ${c||''}">${esc(t)}</span>`;
const stateChip=s=>chip(s==='good'?'Healthy':s==='warn'?'Degraded':'Down',s);
const utilCls=u=>u>=95?'bad':u>=85?'warn':'good';
const tabs=(key,list)=>{const cur=S.tab[key]||list[0][0];return `<div class="tabs" role="tablist">${list.map(t=>`<button class="${cur===t[0]?'on':''}" onclick="S.tab['${key}']='${t[0]}';render()">${esc(t[1])}</button>`).join('')}</div>`};
const curTab=(key,def)=>S.tab[key]||def;
