 const byO={};dv.forEach(d=>byO[d.oem]=(byO[d.oem]||0)+1);const oc={'Palo Alto':'var(--s1)','Cisco':'var(--s2)','Huawei':'var(--s3)','Meraki':'var(--s4)','VeloCloud':'var(--s5)'};
