SCREENS.changes=()=>{const wait=CHANGES.filter(c=>c.state==='Waiting approval');
 return pageHead('Approvals & Changes','What is waiting for a person. Each request carries its plan, evidence and rollback.','')+
 `<div class="grid g3">${tile('Waiting for approval',wait.length,'',wait.length?'c-brand':'')}${tile('Scheduled',CHANGES.filter(c=>c.state==='Scheduled').length,'')}${tile('Closed, verified, 7 days',CHANGES.filter(c=>c.state.startsWith('Closed')).length,'')}</div>
 <div class="grid g2 mt">${wait.map(c=>`<div class="card"><div class="hd"><span class="mono">${c.no}</span>${chip(c.risk,c.risk==='Medium'?'warn':'good')}<span class="note r">${c.when}</span></div><h2>${esc(c.title)}</h2><dl class="kv mt" style="margin-top:8px"><dt>Plan</dt><dd>${esc(c.plan)}</dd><dt>Rollback</dt><dd>${esc(c.back)}</dd><dt>Approver</dt><dd>${esc(c.approver)}</dd></dl><div style="display:flex;gap:8px;margin-top:10px"><button class="btn p sm" onclick="decide('${c.no}',1)">Approve</button><button class="btn sm" onclick="decide('${c.no}',0)">Reject</button></div></div>`).join('')||'<div class="card muted">Nothing is waiting.</div>'}</div>
 <div class="card flush mt"><div class="hd"><h2>All changes</h2></div><div class="tw"><table class="tbl"><thead><tr><th>Change</th><th>Title</th><th>Risk</th><th>When</th><th>State</th></tr></thead><tbody>${CHANGES.map(c=>`<tr><td class="mono">${c.no}</td><td>${esc(c.title)}</td><td>${c.risk}</td><td class="nw">${c.when}</td><td>${c.state}</td></tr>`).join('')}</tbody></table></div></div>
 <div class="card mt"><div class="hd"><h2>When a person must approve</h2></div><div class="grid g3"><div><b>Stage</b><p class="note">Plan, evidence and rollback are prepared, then it waits. Oracle, SAP, firewall policy and DR actions always start here.</p></div><div><b>Act and notify</b><p class="note">Runs inside policy and tells a named person, who can stop it. Service restarts, disk reclaim, endpoint isolation.</p></div><div><b>Autonomous</b><p class="note">Low risk, fully reversible, with a clean record. Password resets, re-running a backup, opening a carrier case.</p></div></div></div>`};
function decide(no,yes){const c=CHANGES.find(x=>x.no===no);c.state=yes?'Scheduled':'Rejected';audit('You',(yes?'Approved ':'Rejected ')+no);toast(yes?'Approved':'Rejected',no+' recorded in the audit log.');frame();render()}

