function matchAsk(t){const stop=new Set(['what','which','when','where','why','how','who','the','and','are','any','for','with','this','that','there','right','now','does','can','you','our','all','much','long','till','until','out','has','have','get','show','tell','about','doing']);const w=t.toLowerCase().replace(/[^a-z0-9 ]/g,' ').split(/\s+/).filter(x=>x.length>2&&!stop.has(x));let best=null,score=0;ASK.forEach(a=>{const hay=(a.k+' '+a.q).toLowerCase();let s=0;w.forEach(x=>{if(hay.includes(x))s+=1;else if(x.length>4&&hay.includes(x.slice(0,4)))s+=.6});if(s>score){score=s;best=a}});return score>=1?best:null}
function ask(t){const a=matchAsk(t);askLog.push({u:t,a:a?a.a():'I can answer questions about site health, incidents, ransomware, backup and DR, approvals, end of support, cloud cost, SLAs, service dependencies and the separation. Try one of the suggestions.',go:a&&a.go});drawAsk()}
