function bootBriefs(){document.documentElement.dataset.theme=S.theme;const m=$('#app');const r=location.hash.slice(1).split('/');const role=BRIEFS[r[0]]?r[0]:null;const ed=r[1]||'today';
 if(!role){m.innerHTML=`<div class="paper"><div class="mast"><h1>Kirby Morning Briefs</h1><div class="note">A two-minute paper for each leader: good news first, a short list to fix, the day ahead. Sample data.</div></div><p>Choose your role.</p><div class="rolegrid">${Object.entries(BRIEFS).map(([k,b])=>`<a class="card" style="text-decoration:none;color:inherit" href="#${k}"><b>${b.name}</b><div class="note" style="margin-top:4px">${b.q}</div></a>`).join('')}</div><p class="mt" style="margin-top:16px"><a href="../index.html">Back to the console</a></p></div>`;return}
 const b=BRIEFS[role],e=b[ed];const d=new Date().toLocaleDateString('en-GB',{weekday:'long',day:'numeric',month:'long',year:'numeric'});
 m.innerHTML=tok(`<div class="paper"><div class="noprint" style="display:flex;gap:8px;margin-bottom:12px;flex-wrap:wrap;align-items:center"><a class="btn sm" href="#">All roles</a><a class="btn sm" href="../index.html">Console</a><div class="seg" style="height:26px">${[['today','Today'],['week','This week'],['month','This month']].map(x=>`<button class="${ed===x[0]?'on':''}" onclick="location.hash='${role}/${x[0]}'">${x[1]}</button>`).join('')}</div><button class="btn sm" style="margin-left:auto" onclick="window.print()">Save as PDF</button></div>
 <div class="mast"><h1>The Kirby Brief</h1><div class="note">${b.name} · ${ed==='today'?d:ed==='week'?'This week':'This month'} · Sample data</div></div><p class="lead">${e.lead}</p>
 <div class="grid g3" style="margin:12px 0">${e.k.map(x=>tile(x[0],x[1])).join('')}</div><h2>Good news</h2><ul>${e.good.map(x=>`<li>${x}</li>`).join('')}</ul><h2>To fix</h2><ul>${e.fix.map(x=>`<li>${x}</li>`).join('')}</ul><h2>${ed==='today'?'The day ahead':ed==='week'?'Next week':'Next month'}</h2><ul>${e.ahead.map(x=>`<li>${x}</li>`).join('')}</ul></div>`)}

/* ---------- boot ---------- */
function bootConsole(){const h=location.hash.slice(1);if(SCREENS[h])S.route=h;frame();render();setInterval(tick,2000);window.addEventListener('hashchange',()=>{const n=location.hash.slice(1);if(SCREENS[n]&&n!==S.route)go(n)})}
function bootDemos(){document.documentElement.dataset.theme=S.theme;$('#app').innerHTML=`<div style="min-height:100vh;display:flex;flex-direction:column"><header class="top" style="height:56px;flex:none"><a class="logo" href="../index.html"><span class="mk">K<i>.</i></span><span><b>Kirby Operations Hub</b><small>Live demos</small></span></a><div class="tsp"></div><a class="btn sm" href="../index.html">Console</a><a class="btn sm hidexs" href="../briefs/index.html">Briefs</a><div class="seg" role="group" aria-label="Tool stack"><button class="${S.stack==='movate'?'on':''}" onclick="setStackD('movate')">Proposed</button><button class="${S.stack==='nexus'?'on':''}" onclick="setStackD('nexus')">NexusNow list</button></div></header><main class="main" id="main" style="margin:0 auto"></main></div><div id="tip"></div><div id="toasts"></div>`;renderGallery();const h=location.hash.slice(1);if(DEMOS.some(d=>d.id===h))openDemo(h);setInterval(()=>{S.now+=2000},2000)}
function setStackD(s){S.stack=s;store.set('stack',s);bootDemos()}
window.addEventListener('DOMContentLoaded',()=>{document.documentElement.dataset.theme=S.theme;const b=window.BOOT||'console';if(b==='demos')bootDemos();else if(b==='briefs'){bootBriefs();window.addEventListener('hashchange',bootBriefs)}else bootConsole()});

